def choose_move(observation):
    def clamp_step(v):
        return -1 if v < 0 else (1 if v > 0 else 0)

    def to_xy(p):
        if p is None:
            return None
        if isinstance(p, (list, tuple)) and len(p) >= 2:
            return p[0], p[1]
        if isinstance(p, dict):
            if "x" in p and "y" in p:
                return p.get("x"), p.get("y")
        return None

    def get_pos(obs):
        for k in ("position", "pos", "agent_pos", "agent_position", "self_pos", "loc"):
            p = to_xy(obs.get(k))
            if p is not None:
                return p
        self_info = obs.get("self")
        if isinstance(self_info, dict):
            for k in ("position", "pos", "agent_pos", "loc"):
                p = to_xy(self_info.get(k))
                if p is not None:
