        return None

    def iter_points(obj):
        if obj is None:
            return
        if isinstance(obj, dict):
            if "x" in obj and "y" in obj:
                yield to_xy(obj)
                return
            for v in obj.values():
                for p in iter_points(v):
                    yield p
        elif isinstance(obj, (list, tuple)):
            if len(obj) == 2 and all(isinstance(v, (int, float)) for v in obj):
                yield (obj[0], obj[1])
                return
            for v in obj:
                for p in iter_points(v):
                    yield p

    def nearest(from_pos, points):
        best = None
        best_d = None
        fx, fy = from_pos
        for p in points:
