    # Terrain / blocking info
    blocked = set()
    for key in ("walls", "obstacles", "blocked", "occupied", "impassable"):
        for p in iter_points(observation.get(key)):
            if p is not None:
                blocked.add((int(p[0]), int(p[1])))

    # Board bounds if present
    width = observation.get("width")
    height = observation.get("height")
