                    # Slight preference for moving to reduce manhattan distance to enemy
                    score += max(-4, 4 - (abs(ex - x) + abs(ey - y)))

            # Mild center bias to avoid walls in empty boards
            if width is not None and height is not None:
                try:
                    cx = (int(width) - 1) / 2.0
                    cy = (int(height) - 1) / 2.0
                    score -= (abs(nx - cx) + abs(ny - cy)) * 0.05
                except Exception:
                    pass

            # Avoid standing on allies if possible
            if (nx, ny) in set((int(a[0]), int(a[1])) for a in allies if a is not None):
                score -= 1

            # Small directional persistence if previous move exists
            prev = observation.get("last_move") or observation.get("previous_move")
            if isinstance(prev, (list, tuple)) and len(prev) >= 2:
